package com.citacloud.app.services; import com.citacloud.app.models.OrdenEstudio; import com.citacloud.app.repositories.OrdenEstudioRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID;
@Service public class OrdenCancelacionService {private final OrdenEstudioRepository ordenes;public OrdenCancelacionService(OrdenEstudioRepository ordenes){this.ordenes=ordenes;}@Transactional public void cancelar(UUID empresaId,UUID ordenId){OrdenEstudio orden=ordenes.findById(ordenId).filter(x->empresaId.equals(x.getEmpresaId())).orElseThrow(()->new IllegalArgumentException("Orden no encontrada."));if("COMPLETADA".equals(orden.getEstado()))throw new IllegalArgumentException("No se puede cancelar una orden completada.");orden.setEstado("CANCELADA");ordenes.save(orden);}}
